def amicable_numbers_sum(n):
    def sum_proper_divisors(x):
        if x <= 1:
            return 0
        total = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
            i += 1
        return total

    def is_amicable(x):
        s = sum_proper_divisors(x)
        return s != x and s > 0 and sum_proper_divisors(s) == x

    total = 0
    for num in range(1, n + 1):
        if is_amicable(num):
            total += num
    return total
```

